import { MeshBasicNodeMaterial } from 'three/webgpu';
import { vec2 } from 'three/tsl';
import { gsap } from 'gsap';
import { Group, Mesh, PlaneGeometry, Color } from 'three/webgpu';

export default function createNode(config, ctx) {
  // Container for the node
  const root = new Group();

  // Placeholder for resources
  let texture = null;
  const geometry = new PlaneGeometry(512 / 320, 1); // aspect ratio from atlas region
  const material = new MeshBasicNodeMaterial({
    color: new Color('#ffffff'), // base color, will be tinted by texture
    map: null,
    transparent: true,
    depthTest: true,
    depthWrite: false,
  });

  const mesh = new Mesh(geometry, material);
  root.add(mesh);

  // Load the sprite texture asynchronously; material will be updated when ready
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      texture = tex;
      material.map = tex;
      material.needsUpdate = true;
    });
  }

  // Event handlers container (none for this node)
  root.userData.handlers = {};

  // Cleanup routine
  root.userData.cleanup = () => {
    // Dispose geometry and material
    geometry.dispose();
    material.dispose();
    // Dispose texture if it was loaded
    if (texture) {
      texture.dispose();
    }
    // Kill any GSAP timelines that might have been created (none for this node)
    gsap.globalTimeline.clear();
  };

  return root;
}
